1	package net.officefloor.hq.app.period;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.time.YearMonth;
6	import java.util.ArrayList;
7	import java.util.Comparator;
8	import java.util.HashMap;
9	import java.util.List;
10	import java.util.Map;
11	import java.util.function.Function;
12	import java.util.stream.Collectors;
13	import net.officefloor.hq.app.Audit;
14	import net.officefloor.hq.app.claim.Claim;
15	import net.officefloor.hq.app.claim.ClaimLog;
16	import net.officefloor.hq.app.claim.ClaimLogRepository;
17	import net.officefloor.hq.app.claim.ClaimRepository;
18	import net.officefloor.hq.app.claim.ClaimStatus;
19	import net.officefloor.hq.app.person.Person;
20	import net.officefloor.hq.app.person.PersonRepository;
21	import net.officefloor.hq.app.rollup.RollupService;
22	import net.officefloor.hq.app.settings.Action;
23	import net.officefloor.hq.app.settings.SettingsService;
24	import net.officefloor.hq.app.sheet.Sheet;
25	import net.officefloor.hq.app.sheet.SheetNotFoundException;
26	import net.officefloor.hq.app.sheet.SheetRepository;
27	import org.springframework.stereotype.Service;
28	import org.springframework.transaction.annotation.Transactional;
29	
30	/** The periods of each sheet: uniquely named, none overlapping another. A period can be closed, which
31	 * fixes its due-total then, and a steward (or the roles the permission matrix allows) can reopen it, which makes its due-total live again. */
32	@Service
33	public class PeriodService {
34	
35	    private final PeriodRepository periods;
36	    private final SheetRepository sheets;
37	    private final ClaimRepository claims;
38	    private final ClaimLogRepository logs;
39	    private final PersonRepository people;
40	    private final RollupService rollup;
41	    private final SettingsService settings;
42	    private final Audit audit;
43	
44	    public PeriodService(PeriodRepository periods, SheetRepository sheets, ClaimRepository claims,
45	            ClaimLogRepository logs, PersonRepository people, RollupService rollup, SettingsService settings, Audit audit) {
46	        this.periods = periods;
47	        this.sheets = sheets;
48	        this.claims = claims;
49	        this.logs = logs;
50	        this.people = people;
51	        this.rollup = rollup;
52	        this.settings = settings;
53	        this.audit = audit;
54	    }
55	
56	    /** The sheet's periods, by from-date. */
57	    @Transactional(readOnly = true)
58	    public List<Period> list(String sheetId) {
59	        return periods.findBySheetIdOrderByFromAsc(sheetId);
60	    }
61	
62	    @Transactional
63	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
64	        return add(sheetId, user, name, from, to, null);
65	    }
66	
67	    /** Add a period capping each person's OPEN or PENDING claims in it at {@code cap} (none when null);
68	     * a cap below one is refused. */
69	    @Transactional
70	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
71	        if (!sheets.existsById(sheetId)) {
72	            throw new SheetNotFoundException();
73	        }
74	        if (to.isBefore(from)) {
75	            throw new PeriodRefusedException("to before from");
76	        }
77	        if (cap != null && cap < 1) {
78	            throw new PeriodRefusedException("cap below one");
79	        }
80	        if (periods.findBySheetIdAndNameKey(sheetId, Period.keyOf(name)).isPresent()) {
81	            throw new PeriodRefusedException("name taken");
82	        }
83	        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
84	            throw new PeriodRefusedException("overlaps");
85	        }
86	        Period period = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
87	        List<String> fields = new ArrayList<>(List.of("period=" + period.getName(), "from=" + period.getFrom(),
88	                "to=" + period.getTo()));
89	        if (cap != null) fields.add("cap=" + cap);
90	        audit.change("PERIOD_ADDED", sheetId, user, fields.toArray(String[]::new));
91	        return period;
92	    }
93	
94	    /** Make one period per calendar month from the from-date's month to the to-date's month, each from
95	     * the first to the last day of its month and named yyyy-mm, in order; a month whose name is
96	     * already a period's or whose days overlap a period on the sheet is left out. A missing date is
97	     * the sheet's today; a to-date before the from-date is refused. */
98	    @Transactional
99	    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
100	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
101	        LocalDate start = from == null ? sheet.getToday() : from;
102	        LocalDate end = to == null ? sheet.getToday() : to;
103	        if (end.isBefore(start)) {
104	            throw new PeriodRefusedException("to before from");
105	        }
106	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromAsc(sheetId));
107	        List<Period> made = new ArrayList<>();
108	        for (YearMonth month = YearMonth.from(start); !month.isAfter(YearMonth.from(end)); month = month.plusMonths(1)) {
109	            String name = month.toString();
110	            LocalDate first = month.atDay(1);
111	            LocalDate last = month.atEndOfMonth();
112	            String key = Period.keyOf(name);
113	            if (existing.stream().anyMatch(p -> Period.keyOf(p.getName()).equals(key) || p.overlaps(first, last))) {
114	                continue;
115	            }
116	            Period period = periods.saveAndFlush(new Period(sheetId, name, first, last));
117	            audit.change("PERIOD_ADDED", sheetId, user, "period=" + period.getName(), "from=" + period.getFrom(),
118	                    "to=" + period.getTo());
119	            existing.add(period);
120	            made.add(period);
121	        }
122	        return made;
123	    }
124	
125	    /** Make the twelve monthly periods of the fiscal year FY{@code year}, the one whose first day is the
126	     * first of the sheet's fiscal start month in {@code year}, exactly as {@link #generate} would. */
127	    @Transactional
128	    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
129	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
130	        YearMonth first = YearMonth.of(year, sheet.getFiscalStartMonth());
131	        return generate(sheetId, user, first.atDay(1), first.plusMonths(11).atEndOfMonth());
132	    }
133	
134	    /** Close the period, fixing its due-total and each person's carried figure into it now (afresh when it was soft-closed); refused when the
135	     * user's role may not close (see {@link SettingsService#allowed}) or it is already closed, not
136	     * only soft-closed. */
137	    @Transactional
138	    public Period close(String sheetId, String user, long periodId) {
139	        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
140	        if (!settings.allowed(sheetId, user, Action.CLOSE)) {
141	            throw new PeriodNotStewardException();
142	        }
143	        if (period.isClosed() && !period.isSoft()) {
144	            throw new PeriodRefusedException("already closed");
145	        }
146	        return close(period, user);
147	    }
148	
149	    /** Soft-close the period, fixing its due-total now while claims dated in it can still change;
150	     * refused as {@link #close(String, String, long)} is, and when it is already closed or soft-closed. */
151	    @Transactional
152	    public Period softClose(String sheetId, String user, long periodId) {
153	        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
154	        if (!settings.allowed(sheetId, user, Action.CLOSE)) {
155	            throw new PeriodNotStewardException();
156	        }
157	        if (period.isClosed()) {
158	            throw new PeriodRefusedException("already closed");
159	        }
160	        period.close(personTotalsOf(period), personCarriedOf(period), true);
161	        periods.flush();
162	        audit.change("PERIOD_SOFT_CLOSED", sheetId, user, "period=" + period.getName(),
163	                "total=" + period.getClosedTotal().toPlainString());
164	        return period;
165	    }
166	
167	    /** Close, as {@link #close(String, String, long)} would, every open period of the sheet whose to-date
168	     * plus its grace days is before its today, in order of their to-dates, each marked auto=yes; nothing
169	     * when the grace days are off. An automatic close is not subject to the permission matrix. */
170	    @Transactional
171	    public void closeOverdue(String sheetId, String user) {
172	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
173	        Integer grace = sheet.getGraceDays();
174	        if (grace == null) return;
175	        List<Period> due = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
176	                .filter(p -> !p.isClosed() && p.getTo().plusDays(grace).isBefore(sheet.getToday()))
177	                .sorted(Comparator.comparing(Period::getTo)).toList();
178	        for (Period open : due) {
179	            Period period = periods.lockByIdAndSheetId(open.getId(), sheetId).orElseThrow(PeriodNotFoundException::new);
180	            if (!period.isClosed()) close(period, user, "auto=yes");
181	        }
182	    }
183	
184	    private Period close(Period period, String user, String... extra) {
185	        period.close(personTotalsOf(period), personCarriedOf(period));
186	        periods.flush();
187	        List<String> fields = new ArrayList<>(List.of("period=" + period.getName(),
188	                "total=" + period.getClosedTotal().toPlainString()));
189	        fields.addAll(List.of(extra));
190	        audit.change("PERIOD_CLOSED", period.getSheetId(), user, fields.toArray(String[]::new));
191	        return period;
192	    }
193	
194	    /** Reopen the period, making its due-total and the carried figures into it live again; refused when the user's role may not
195	     * reopen (a steward's by default, see {@link SettingsService#allowed}) or the period is not closed
196	     * or soft-closed. */
197	    @Transactional
198	    public Period reopen(String sheetId, String user, long periodId) {
199	        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
200	        if (!settings.allowed(sheetId, user, Action.REOPEN)) {
201	            throw new PeriodNotStewardException();
202	        }
203	        if (!period.isClosed()) {
204	            throw new PeriodRefusedException("not closed");
205	        }
206	        period.reopen();
207	        periods.flush();
208	        audit.change("PERIOD_REOPENED", sheetId, user, "period=" + period.getName());
209	        return period;
210	    }
211	
212	    /** Each person's due-total for the period now, by person id, for everyone on the sheet: the sum of
213	     * what is due on their claims whose due-by falls in it that counted by the status each had at the end of the
214	     * period's last day (see {@link #statusAt}), as each shows it now, late charges included (a
215	     * claim with no figure adds nothing, nor does an OPEN claim deferred on the sheet's today or an unbound OPEN claim dated within one of its person's holds, while the claim is still OPEN or PENDING now). */
216	    private Map<Long, BigDecimal> personTotalsOf(Period period) {
217	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(period.getSheetId()).stream()
218	                .collect(Collectors.toMap(Person::getId, Function.identity()));
219	        Map<Long, BigDecimal> totals = new HashMap<>();
220	        for (Long id : byId.keySet()) totals.put(id, BigDecimal.ZERO.setScale(2));
221	        LocalDate today = sheets.findById(period.getSheetId()).map(Sheet::getToday).orElse(null);
222	        List<Claim> dated = claims.findBySheetIdOrderByListedDescIdDesc(period.getSheetId()).stream()
223	                .filter(claim -> period.overlaps(claim.getDueBy(), claim.getDueBy())).toList();
224	        Map<Long, List<ClaimLog>> logsOf = dated.isEmpty() ? Map.of()
225	                : logs.findByClaimIdInOrderByIdAsc(dated.stream().map(Claim::getId).toList()).stream()
226	                        .collect(Collectors.groupingBy(ClaimLog::getClaimId));
227	        for (Claim claim : dated) {
228	            Person person = byId.get(claim.getPersonId());
229	            ClaimStatus status = statusAt(logsOf.getOrDefault(claim.getId(), List.of()), period.getTo());
230	            if (person == null || status == null) continue;
231	            boolean counts = claim.getStatus().isOpen() ? RollupService.countsAs(claim, status, person, today) : status.counts();
232	            if (!counts) continue;
233	            BigDecimal figure = rollup.shownOf(claim, person);
234	            if (figure != null) totals.merge(person.getId(), figure, BigDecimal::add);
235	        }
236	        return totals;
237	    }
238	
239	    /** Each person's carried figure into the period now, by person id, for everyone on the sheet: the sum
240	     * of what is due on their claims whose due-by falls in a period of the sheet ending before this one
241	     * starts and that were still OPEN or PENDING at the end of this one's last day (see {@link #statusAt}),
242	     * and their opening balance for it,
243	     * as each shows it now (a claim with no figure adds nothing, nor does one that would not count then,
244	     * as {@link #personTotalsOf} counts). */
245	    private Map<Long, BigDecimal> personCarriedOf(Period period) {
246	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(period.getSheetId()).stream()
247	                .collect(Collectors.toMap(Person::getId, Function.identity()));
248	        Map<Long, BigDecimal> carried = new HashMap<>();
249	        for (Long id : byId.keySet()) carried.put(id, BigDecimal.ZERO.setScale(2));
250	        period.getPersonOpenings().forEach((id, opening) -> {
251	            if (byId.containsKey(id)) carried.merge(id, opening, BigDecimal::add);
252	        });
253	        LocalDate today = sheets.findById(period.getSheetId()).map(Sheet::getToday).orElse(null);
254	        List<Period> all = periods.findBySheetIdOrderByFromAsc(period.getSheetId());
255	        if (all.stream().noneMatch(p -> p.getTo().isBefore(period.getFrom()))) return carried;
256	        List<Claim> before = claims.findBySheetIdOrderByListedDescIdDesc(period.getSheetId()).stream()
257	                .filter(claim -> claim.getDueBy() != null)
258	                .filter(claim -> all.stream().filter(p -> p.overlaps(claim.getDueBy(), claim.getDueBy())).findFirst()
259	                        .map(own -> own.getTo().isBefore(period.getFrom())).orElse(false))
260	                .toList();
261	        Map<Long, List<ClaimLog>> logsOf = before.isEmpty() ? Map.of()
262	                : logs.findByClaimIdInOrderByIdAsc(before.stream().map(Claim::getId).toList()).stream()
263	                        .collect(Collectors.groupingBy(ClaimLog::getClaimId));
264	        for (Claim claim : before) {
265	            Person person = byId.get(claim.getPersonId());
266	            ClaimStatus status = statusAt(logsOf.getOrDefault(claim.getId(), List.of()), period.getTo());
267	            if (person == null || status == null || !status.isOpen()) continue;
268	            boolean counts = claim.getStatus().isOpen() ? RollupService.countsAs(claim, status, person, today) : status.counts();
269	            if (!counts) continue;
270	            BigDecimal figure = rollup.shownOf(claim, person);
271	            if (figure != null) carried.merge(person.getId(), figure, BigDecimal::add);
272	        }
273	        return carried;
274	    }
275	
276	    /** The status a claim had at the end of {@code day}, by its status log, oldest first, whose lines
277	     * are dated with the sheet's today when each change was made; null when it was added after. */
278	    private static ClaimStatus statusAt(List<ClaimLog> log, LocalDate day) {
279	        ClaimStatus status = null;
280	        for (ClaimLog line : log) {
281	            if (line.getDate().isAfter(day)) break;
282	            status = line.getStatus();
283	        }
284	        return status;
285	    }
286	}
